Ltac rdb :=
  lazymatch goal with
  | |- CRep.fld _ (wbytes ?Mi (Z_to_bv 64 ?a) (word_to_le_bytes _ ?w)) ?b _ _ =>
      first [ replace b with a by lia; first [rewrite <- (zbv_u w) | idtac]; first [apply fld_wbytes8 | apply fld_wbytes4]; lia
            | eapply (fld_agree _ Mi);
              [ lia | cbn; lia | rdb
              | eapply stores_in_agree;
                [ apply stores_in_wbytes; [lia | rewrite length_N_to_le_bytes; cbn; lia | intros x Hx; exact Hx]
                | intros y Hy; unfold zwin in Hy; cbn in Hy; rewrite ?length_N_to_le_bytes; cbn; lia ] ] ]
  | |- CRep.fld _ _ _ _ _ => assumption
  end.

