Ltac reg_goal HRx :=
  lazymatch goal with |- getr _ ?r = _ =>
    let G := fresh in rreg HRx r G; rewrite G; evs; rewrite ?v_addi_Z, ?zbv_add by lia;
    first [reflexivity | assumption | f_equal; lia | apply bv_eq; vm_compute; reflexivity] end.
Ltac st_goal :=
  evs; rewrite ?v_addi_Z by lia;
  first [ apply stores_in_refl
        | repeat (eapply stores_in_wbytes_more; [ | lia | rewrite length_N_to_le_bytes; cbn; lia | rewrite length_N_to_le_bytes; unfold zwin; cbn; intros; lia ]);
          first [ apply stores_in_refl
                | apply stores_in_wbytes; [lia | rewrite length_N_to_le_bytes; cbn; lia | rewrite length_N_to_le_bytes; unfold zwin; cbn; intros; lia] ] ].
Ltac seg_close E Rn :=
  lazymatch goal with HRx : regs_ok E _ ?Rx |- _ =>
  lazymatch goal with Hmsx : msteps _ (mkst Rn _ _ _) (mkst Rx _ _ _) |- _ =>
    eexists; eexists; split; [exact Hmsx|];
    split; [st_goal|];
    split; [exact (syms_id_sound _ _ _ Rx CS2 HRx eq_refl)|];
    repeat split; reg_goal HRx end end.
Ltac seg_close_ret E Rn Hra Hret :=
  lazymatch goal with HRx : regs_ok E _ ?Rx |- _ =>
  lazymatch goal with Hmsx : msteps _ (mkst Rn _ _ _) (mkst Rx _ _ _) |- _ =>
    let Hra1 := fresh "Hra1" in
    assert (Hra1 : getr Rx 1%bv = getr _ 1%bv) by (let G := fresh in rreg HRx 1%bv G; rewrite G; evs; reflexivity);
    rewrite Hra in Hra1;
    eexists; eexists; split; [eapply msteps_trans; [exact Hmsx | eapply ret_run; [vm_compute; reflexivity | exact Hra1 | exact Hret]] |];
    split; [st_goal|];
    split; [exact (syms_id_sound _ _ _ Rx CS2 HRx eq_refl)|];
    repeat split; reg_goal HRx end end.

